// The Android release build runs KSP (expo-updates) and lint in the Gradle daemon; with the
// template's 2 GB heap / 512 MB metaspace it dies with "OutOfMemoryError: Metaspace". Give the Gradle
// and Kotlin daemons room. android/ is regenerated by prebuild, so this lives here, not there.
const { withGradleProperties } = require("expo/config-plugins");

const PROPS = {
  "org.gradle.jvmargs": "-Xmx6g -XX:MaxMetaspaceSize=2g -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8",
  "kotlin.daemon.jvmargs": "-Xmx4g -XX:MaxMetaspaceSize=1g",
};

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (c) => {
    for (const [key, value] of Object.entries(PROPS)) {
      const hit = c.modResults.find((p) => p.type === "property" && p.key === key);
      if (hit) hit.value = value;
      else c.modResults.push({ type: "property", key, value });
    }
    return c;
  });
};
